<script setup lang="ts">
import { computed, ref } from 'vue'
import { useLocale } from '../composables/useLocale'
import { imageList } from '../utils/image'
const { isEn } = useLocale()
const boundary = ref<'none' | 'box' | 'wrapper'>('box')
const modes = computed(() => isEn.value ? [{ value: 'none', title: 'No constraint' }, { value: 'box', title: 'Cover the crop box' }, { value: 'wrapper', title: 'Cover the workspace' }] : [{ value: 'none', title: '无边界约束' }, { value: 'box', title: '覆盖裁剪框' }, { value: 'wrapper', title: '覆盖整个容器' }])
</script>
